    subjectName: '予報業務に関する一般知識',
    question: '日没・日出時にごく短時間観測されることがある「グリーンフラッシュ」の発生原理に関する記述として正しいものはどれか。',
    choices: [
      { key: 'A', text: 'グリーンフラッシュは、大気による光の屈折率が波長によってわずかに異なる（波長の短い光ほど強く屈折する）ことを背景に、日没・日出の際に太陽の上端付近から赤色より波長の短い緑色の光が最後（あるいは最初）に見えることで生じる現象であり、大気の状態が安定し見通しが良い水平線付近で観測されやすい。', explanation: '正しい。大気による光の屈折は波長に依存し（大気による分散）、波長の短い緑や青の光の方が波長の長い赤色光よりも強く屈折する。太陽が水平線に沈む（あるいは昇る）際、この屈折の波長依存性により太陽の像の色が上端でわずかにずれ、赤色の光が沈んだ後の一瞬、緑色の光が見えることがある（青色はさらに大気による散乱で弱まりやすいため通常は緑色として観測される）。この現象は大気が安定し見通しが良い、水平線が開けた条件下で観測されやすい。' },
      { key: 'B', text: 'グリーンフラッシュは大気中の緑色の物質（緑藻など）が太陽光を反射することで生じる現象である。', explanation: '誤り。グリーンフラッシュは大気による光の屈折の波長依存性（分散）によって生じる光学現象であり、緑色の物質による反射とは無関係である。' },
      { key: 'C', text: 'グリーンフラッシュは大気が非常に不安定で乱れている条件でのみ、頻繁に長時間観測される現象である。', explanation: '誤り。グリーンフラッシュはむしろ大気が安定し見通しが良い条件で観測されやすく、また現象自体はごく短時間（数秒未満）しか継続しない現象である。' },
      { key: 'D', text: 'グリーンフラッシュの発生には大気の屈折は全く関係せず、専ら雲による光の反射によって生じる。', explanation: '誤り。グリーンフラッシュの本質的な発生原理は大気による光の屈折の波長依存性（分散）であり、雲による反射とは異なる物理過程である。' },
    ],
