    question: '大気の予測可能性の限界（カオス的性質）に関する記述として正しいものはどれか。',
    choices: [
      { key: 'A', text: '大気の運動を支配する方程式は非線形性が強いカオス的な性質を持つため、初期値のごくわずかな誤差が時間とともに指数関数的に増大していく性質があり、この誤差成長の速さの目安となる特徴的な時間スケールをリヤプノフ時間（あるいは予測可能性の限界）という。', explanation: '正しい。大気の支配方程式（ナビエ・ストークス方程式等に基づく流体力学の方程式系）は本質的に非線形でカオス的な性質を持ち、どんなにわずかな初期値の誤差でも時間とともに指数関数的に増大する（バタフライ効果として知られる性質）。この誤差が2倍（あるいはe倍）に増大するのに要する特徴的な時間スケールをリヤプノフ時間といい、大気の総観規模現象ではおおむね数日程度とされ、これが決定論的な数値予報の実質的な予測可能性の限界（およそ2週間程度が理論的な上限とされる）を規定する一因となっている。' },
      { key: 'B', text: '大気の運動は完全に線形な方程式で記述され、初期値の誤差は時間とともに増大せず一定に保たれる。', explanation: '誤り。大気の運動を記述する方程式は非線形性が強くカオス的な性質を持つため、初期値の誤差は時間とともに一定にとどまらず、指数関数的に増大する性質がある。' },
      { key: 'C', text: 'リヤプノフ時間が長いほど、その系の予測可能性は低い（予測が難しい）ことを意味する。', explanation: '誤り。リヤプノフ時間は誤差が指数関数的に増大する速さの目安であり、リヤプノフ時間が「短い」ほど誤差の増大が速く予測可能性が低い（予測が難しい）ことを意味する。リヤプノフ時間が長いほど誤差の増大が遅く予測可能性は高い。' },
      { key: 'D', text: '数値予報の計算機の性能が十分に向上すれば、大気の予測可能性の限界（理論的な限界）は将来的に完全になくなる。', explanation: '誤り。予測可能性の限界は大気のカオス的な性質（初期値の誤差の指数関数的増大）という本質的な物理的性質に起因するものであり、計算機の性能向上（分解能や計算速度の向上）だけでこの理論的な限界を完全になくすことはできないと考えられている。' },
    ],
